import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecurePathTraversalExample {
    public static void main(String[] args) {
        String userInput = "../../../etc/passwd";
        String baseDir = "/var/www/uploads";

        try {
            // Construct the full path using Paths.get() which handles separators safely
            Path basePath = Paths.get(baseDir).toAbsolutePath().normalize();
            Path requestedPath = Paths.get(baseDir, userInput).toAbsolutePath().normalize();

            // Ensure the resolved path is strictly within the intended base directory
            if (!requestedPath.startsWith(basePath)) {
                throw new SecurityException("Access denied: Attempted path traversal detected.");
            }

            File safeFile = requestedPath.toFile();
            System.out.println("Successfully accessing: " + safeFile.getAbsolutePath());

        } catch (SecurityException e) {
            System.err.println("Blocked request: " + e.getMessage());
        }
    }
}
